import type { OrderRepository } from './interfaces.js'

export class OrderService {
  readonly #orders: OrderRepository

  constructor (orders: OrderRepository) {
    this.#orders = orders
  }

  async rename (id: string, name: string) {
    return await this.#orders.update(id, { name })
  }
}

import type { ModelStatic } from 'sequelize'
import type { OrderRow } from './orderModel.js'

export class PostgresOrderRepository {
  readonly #table: ModelStatic<OrderRow>

  constructor (table: ModelStatic<OrderRow>) {
    this.#table = table
  }

  async findById (id: string) {
    const row = await this.#table.findByPk(id)
    return row === null ? null : { id: row.id }
  }
}

