import type { PostgresConfig } from './postgresConfig.js'

interface Authenticatable {
  authenticate: () => Promise<void>
}

export const createConnection = async function <T extends Authenticatable>(
  postgres: PostgresConfig,
  SequelizeClass: new (connectString: string, options: object) => T,
): Promise<T> {
  const connectString = `postgres://${postgres.user}:${postgres.password}@${postgres.host}:${postgres.port}/${postgres.database}`
  const sequelize = new SequelizeClass(connectString, {
    dialectOptions: { ssl: true },
    pool: { max: 7, min: 0, acquire: 30000, idle: 10000 },
  })
  await sequelize.authenticate()
  return sequelize
}

import type { PostgresConfig } from './postgresConfig.js'

interface Authenticatable {
  authenticate: () => Promise<void>
}

export const createConnection = async function <T extends Authenticatable>(
  postgres: PostgresConfig,
  SequelizeClass: new (connectString: string, options: object) => T,
): Promise<T> {
  const connectString = `postgres://${postgres.user}:${postgres.password}@${postgres.host}:${postgres.port}/${postgres.database}`
  const sequelize = new SequelizeClass(connectString, {
    dialectOptions: { ssl: true, statement_timeout: 30000 },
    pool: { max: 7, min: 0, acquire: 30000, idle: 10000 },
  })
  await sequelize.authenticate()
  return sequelize
}

